new=r'''def hardware_page(project):
 return """<!doctype html><html lang='de'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><script type='module' src='https://unpkg.com/esp-web-tools@10/dist/web/install-button.js?module'></script><style>body{font-family:system-ui;margin:20px;background:#111827;color:#e5e7eb}.card{background:#1f2937;padding:16px;border-radius:14px;margin:12px 0}button{padding:8px;margin:3px}pre{background:#030712;padding:12px;min-height:220px;white-space:pre-wrap}a{color:#93c5fd}.ok{color:#86efac}.warn{color:#fbbf24}.bad{color:#fca5a5}</style></head><body><h1>USB & Status: PROJECT</h1><div class='card'><h2>USB-Erstinstallation</h2><div id='manifestState'>Prüfe Manifest ...</div><esp-web-install-button id='installer'></esp-web-install-button></div><div class='card'><h2>Serieller Monitor</h2><button id='connectButton' onclick='connectSerial()'>Verbinden</button><button id='disconnectButton' onclick='disconnectSerial()' disabled>Trennen</button><button onclick='document.getElementById("serialLog").textContent=""'>Leeren</button><span id='serialState'>Nicht verbunden</span><pre id='serialLog'></pre></div><div class='card'><h2>WLAN</h2><p>Nach dem Flash mit <b>ESPManager-PROJECT</b> verbinden. Falls nötig 192.168.4.1 öffnen.</p></div><div class='card'><h2>MQTT-Status</h2><p class='warn'>Status 5 bedeutet: Broker hat die Anmeldung nicht autorisiert. In den Add-on-Optionen müssen device_mqtt_username und device_mqtt_password zu einem Mosquitto-Gerätebenutzer passen. Danach neu kompilieren und flashen.</p><pre id='deviceStatus'>Noch kein Status</pre></div><a href='../..'>Zurück</a><script>let port=null,reader=null,readLoopPromise=null,keepReading=false;const decoder=new TextDecoder();async function checkManifest(){try{let base=location.pathname.endsWith('/')?location.pathname:location.pathname+'/';let url=base+'manifest.json';document.getElementById('installer').setAttribute('manifest',url);let r=await fetch(url,{cache:'no-store'});if(!r.ok)throw Error(await r.text());let m=await r.json();document.getElementById('manifestState').className='ok';document.getElementById('manifestState').textContent='Bereit: '+m.name+' '+m.version+' / '+m.builds[0].chipFamily}catch(e){document.getElementById('manifestState').className='bad';document.getElementById('manifestState').textContent='Manifest-Fehler: '+e.message}}async function readSerial(){try{while(keepReading&&port&&port.readable){reader=port.readable.getReader();try{while(keepReading){const result=await reader.read();if(result.done)break;if(result.value){const el=document.getElementById('serialLog');el.textContent+=decoder.decode(result.value,{stream:true});el.scrollTop=el.scrollHeight}}}catch(e){if(keepReading)document.getElementById('serialLog').textContent+='\\nLesefehler: '+e.message}finally{try{reader.releaseLock()}catch(e){}reader=null}}}finally{}}async function connectSerial(){if(port)return;try{if(!navigator.serial)throw Error('Web Serial wird nicht unterstützt');port=await navigator.serial.requestPort();await port.open({baudRate:115200});keepReading=true;document.getElementById('serialState').textContent='Verbunden';document.getElementById('connectButton').disabled=true;document.getElementById('disconnectButton').disabled=false;readLoopPromise=readSerial()}catch(e){port=null;document.getElementById('serialState').textContent='Fehler: '+e.message}}async function disconnectSerial(){if(!port)return;keepReading=false;document.getElementById('disconnectButton').disabled=true;try{if(reader)await reader.cancel();if(readLoopPromise)await readLoopPromise;await port.close();document.getElementById('serialState').textContent='Getrennt'}catch(e){document.getElementById('serialState').textContent='Trennfehler: '+e.message}finally{reader=null;readLoopPromise=null;port=null;document.getElementById('connectButton').disabled=false}}async function refreshStatus(){try{let r=await fetch('../../api/devices/PROJECT');if(!r.ok)throw Error(await r.text());document.getElementById('deviceStatus').textContent=JSON.stringify(await r.json(),null,2)}catch(e){document.getElementById('deviceStatus').textContent='Noch kein MQTT-Status: '+e.message}}checkManifest();refreshStatus();setInterval(refreshStatus,5000)</script></body></html>""".replace('PROJECT',clean(project))
'''
